#!/usr/bin/env python3
"""Compile the actual MDX fence and compare it against all small graph realizations.
Usage: python3 checker.py [article.mdx] [--sanitize]
"""
from pathlib import Path
import os
import shutil
import re
import subprocess
import sys
import tempfile
DEFAULT = Path(__file__).resolve().parents[1] / "src/content/docs/techniques/simple-path-count-matrix-tree-cycle-construction.mdx"
args = [arg for arg in sys.argv[1:] if arg != "--sanitize"]
article = Path(args[0]) if args else DEFAULT
blocks = re.findall(r"^```cpp\s*\n(.*?)^```\s*$", article.read_text(), re.M | re.S)
if len(blocks) != 1:
    raise RuntimeError("expected exactly one complete visible C++ fence")
TESTS = '#include <algorithm>\n#include <chrono>\n#include <cstdint>\n#include <cstdlib>\n#include <functional>\n#include <iostream>\n#include <limits>\n#include <unordered_set>\nusing Matrix = std::vector<std::vector<int>>;\nstd::uint64_t checks=0, all_graphs=0, all_matrices=0, constructed_rechecks=0, three_graphs=0;\nvoid require(bool ok,const char* reason) {\n    ++checks;\n    if(!ok) {std::cerr<<"FAIL: "<<reason<<\'\\n\';std::exit(1);}\n}\n// Count every vertex-distinct path directly. No block/cycle/partition logic.\nMatrix path_counts(const Matrix& graph) {\n    int n=int(graph.size());std::vector<std::vector<int>> adjacent(n);\n    for(int u=0;u<n;++u) {\n        require(int(graph[u].size())==n,"returned adjacency shape");\n        for(int v=0;v<n;++v) {\n            require(graph[u][v]==0||graph[u][v]==1,"binary adjacency");\n            require(graph[u][v]==graph[v][u],"undirected adjacency");\n            if(u==v) require(graph[u][v]==0,"no self loops");\n            if(graph[u][v]) adjacent[u].push_back(v);\n        }\n    }\n    Matrix counts(n,std::vector<int>(n,0));\n    std::vector<unsigned char> visited(n,0);\n    for(int source=0;source<n;++source) {\n        auto dfs=[&](auto&& self,int vertex)->void {\n            ++counts[source][vertex];visited[vertex]=1;\n            for(int next:adjacent[vertex]) if(!visited[next]) self(self,next);\n            visited[vertex]=0;\n        };\n        dfs(dfs,source);\n    }\n    return counts;\n}\nstd::uint64_t encode(const Matrix& matrix) {\n    std::uint64_t value=0;int at=0;\n    for(int u=0;u<int(matrix.size());++u) for(int v=u+1;v<int(matrix.size());++v) {\n        value|=std::uint64_t(matrix[u][v])<<(2*at);++at;\n    }\n    return value;\n}\nMatrix decode(int n,std::uint64_t value) {\n    Matrix matrix(n,std::vector<int>(n));\n    for(int u=0;u<n;++u) {\n        matrix[u][u]=1;\n        for(int v=u+1;v<n;++v) {matrix[u][v]=matrix[v][u]=int(value&3);value>>=2;}\n    }\n    return matrix;\n}\nvoid recheck(const Matrix& required,const std::optional<SimpleAdjacency>& result) {\n    require(result.has_value(),"known-realizable matrix rejected");\n    require(path_counts(*result)==required,"all pairs in the returned graph match the matrix");\n    ++constructed_rechecks;\n}\nvoid exhaustive() {\n    for(int n=1;n<=6;++n) {\n        int pairs=n*(n-1)/2;\n        std::unordered_set<std::uint64_t> realizable;\n        for(std::uint64_t edges=0;edges<(std::uint64_t{1}<<pairs);++edges) {\n            Matrix graph(n,std::vector<int>(n));int bit=0;\n            for(int u=0;u<n;++u) for(int v=u+1;v<n;++v) {graph[u][v]=graph[v][u]=(edges>>bit)&1;++bit;}\n            Matrix required=path_counts(graph);int largest=0;bool has_three=false;\n            for(const auto& row:required) for(int count:row) {largest=std::max(largest,count);has_three|=count==3;}\n            if(has_three) {++three_graphs;require(largest>=4,"any graph having a 3-path pair has a >=4-path pair");}\n            if(largest<=3) {\n                realizable.insert(encode(required));\n                recheck(required,construct_simple_path_count_graph(required));\n            }\n            ++all_graphs;\n        }\n        if(n<=5) for(std::uint64_t code=0;code<(std::uint64_t{1}<<(2*pairs));++code) {\n            Matrix required=decode(n,code);\n            const auto result=construct_simple_path_count_graph(required);\n            bool expected=realizable.contains(code);\n            require(result.has_value()==expected,"all symmetric 0..3 matrices / exhaustive graph realizability oracle");\n            if(result) recheck(required,result);\n            ++all_matrices;\n        }\n    }\n}\nMatrix block_matrix(int n,const std::vector<int>& component,const std::vector<int>& cls) {\n    Matrix result(n,std::vector<int>(n));\n    for(int u=0;u<n;++u) for(int v=0;v<n;++v)\n        result[u][v]=component[u]!=component[v]?0:cls[u]==cls[v]?1:2;\n    return result;\n}\nvoid explicit_and_large() {\n    recheck({{1,1,2,2},{1,1,2,2},{2,2,1,2},{2,2,2,1}},construct_simple_path_count_graph({{1,1,2,2},{1,1,2,2},{2,2,1,2},{2,2,2,1}}));\n    recheck({{1,0},{0,1}},construct_simple_path_count_graph({{1,0},{0,1}}));\n    require(!construct_simple_path_count_graph({{1,3},{3,1}}),"official impossible example");\n    require(!construct_simple_path_count_graph({{1,2},{2,1}}),"two classes cannot make a simple cycle");\n    recheck({{1}},construct_simple_path_count_graph({{1}}));\n    const int n=1000;\n    std::vector<int> component(n),cls(n);\n    Matrix required(n,std::vector<int>(n,1));\n    recheck(required,construct_simple_path_count_graph(required));\n    for(int v=0;v<n;++v) component[v]=v;\n    required=block_matrix(n,component,component);recheck(required,construct_simple_path_count_graph(required));\n    std::fill(component.begin(),component.end(),0);\n    for(int v=0;v<n;++v) cls[v]=v;\n    required=block_matrix(n,component,cls);recheck(required,construct_simple_path_count_graph(required));\n    for(int v=0;v<n;++v) {component[v]=v/100;cls[v]=5*(v/100)+(v%100)/20;}\n    required=block_matrix(n,component,cls);recheck(required,construct_simple_path_count_graph(required));\n    std::fill(component.begin(),component.end(),0);for(int v=0;v<n;++v) cls[v]=v/500;\n    require(!construct_simple_path_count_graph(block_matrix(n,component,cls)),"maximum two-class rejection");\n    required.assign(n,std::vector<int>(n,1));required[n-2][n-1]=required[n-1][n-2]=2;\n    require(!construct_simple_path_count_graph(required),"maximum late uniqueness/transitivity violation");\n    required[n-2][n-1]=required[n-1][n-2]=3;\n    require(!construct_simple_path_count_graph(required),"maximum three-path rejection");\n    for(int v=0;v<n;++v) component[v]=v;\n    required=block_matrix(n,component,component);\n    required[0][n-1]=required[n-1][0]=1;required[n-2][n-1]=required[n-1][n-2]=1;\n    require(!construct_simple_path_count_graph(required),"maximum positive-relation violation");\n    // These orders deliberately exceed the former artificial API cap.\n    // Every returned pair is independently counted by the DFS oracle above.\n    for (int larger : {1001,2000}) {\n        Matrix large(larger,std::vector<int>(larger,1));\n        recheck(large,construct_simple_path_count_graph(large)); // one tree\n        for (int u=0;u<larger;++u) for (int v=0;v<larger;++v)\n            large[u][v]=u==v?1:0;\n        recheck(large,construct_simple_path_count_graph(large)); // isolated vertices\n        for (int u=0;u<larger;++u) for (int v=0;v<larger;++v)\n            large[u][v]=u==v?1:2;\n        recheck(large,construct_simple_path_count_graph(large)); // one long cycle\n        for (int u=0;u<larger;++u) for (int v=0;v<larger;++v) {\n            int cu=u/200,cv=v/200;\n            large[u][v]=cu!=cv?0:(u%200)/40==(v%200)/40?1:2;\n        }\n        recheck(large,construct_simple_path_count_graph(large)); // trees on several cycles\n    }\n}\ntemplate<class F> void invalid(F action) {\n    bool threw=false;try{action();}catch(const std::invalid_argument&){threw=true;}\n    require(threw,"invalid matrix must throw");\n}\nvoid invalid_cases() {\n    invalid([]{construct_simple_path_count_graph({});});\n    invalid([]{construct_simple_path_count_graph({{1,0},{0}});});\n    invalid([]{construct_simple_path_count_graph({{1,3},{}});});\n    invalid([]{construct_simple_path_count_graph({{1,0,0},{0,1},{0,0,1}});});\n    invalid([]{construct_simple_path_count_graph({{1,1},{0,1}});});\n    invalid([]{construct_simple_path_count_graph({{1,3},{0,1}});});\n    for(int diagonal:{0,2,3,-1,4,std::numeric_limits<int>::min(),std::numeric_limits<int>::max()})\n        invalid([&]{construct_simple_path_count_graph({{diagonal}});});\n    for(int value:{-1,4,std::numeric_limits<int>::min(),std::numeric_limits<int>::max()})\n        invalid([&]{construct_simple_path_count_graph({{1,value},{value,1}});});\n}\nint main() {\n    auto start=std::chrono::steady_clock::now();\n    exhaustive();explicit_and_large();invalid_cases();\n    std::cout<<"checks="<<checks<<" all_graphs="<<all_graphs<<" all_symmetric_matrices="<<all_matrices\n             <<" returned_graph_rechecks="<<constructed_rechecks<<" three_path_graphs="<<three_graphs\n             <<" total_seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<\'\\n\';\n}\n'
with tempfile.TemporaryDirectory(prefix="flowchartcp-supertrees-") as directory:
    source = Path(directory) / "check.cpp"
    binary = Path(directory) / "check"
    source.write_text(blocks[0] + "\n" + TESTS)
    flags = ["-std=c++20", "-O2", "-Wall", "-Wextra", "-Werror"]
    environment = os.environ.copy()
    if "--sanitize" in sys.argv:
        flags += ["-g", "-fsanitize=address,undefined", "-fno-omit-frame-pointer"]
        environment["ASAN_OPTIONS"] = "detect_leaks=0"
    compiler = os.environ.get("CXX") or shutil.which("g++") or shutil.which("clang++") or "c++"
    subprocess.run([compiler, *flags, str(source), "-o", str(binary)], check=True, timeout=120)
    subprocess.run([str(binary)], check=True, env=environment, timeout=180)
